import pandas as pd,numpy as np,json,sys
current=int(sys.argv[1]);last=current-1
h=pd.read_csv('/app/normalized_history.csv');t=pd.read_csv('/app/target_history.csv');cities={'San Francisco':'LOC01','New York':'LOC02','Chicago':'LOC03'};catalog=pd.read_json('data/furniture.json');extra=t.merge(catalog,on='furniture_name');extra['location_id']=extra.locality.map(cities);d=pd.concat([h,extra],ignore_index=True).drop_duplicates(['location_id','year','furniture_id'],keep='last');d=d[d.year<=last];d['logq']=np.log(d.items_sold);d['key']=d.location_id.astype(str)+'_'+d.furniture_id.astype(str)
slopes={}
for typ,g in d.groupby('furniture_type'):
 x=g.year-g.groupby('key').year.transform('mean');y=g.logq-g.groupby('key').logq.transform('mean');den=float(np.dot(x,x))
 if den>0:slopes[typ]=float(np.dot(x,y)/den)
rows=[];fits={};mapping=catalog.set_index('furniture_name').furniture_type.to_dict()
for name,g in t.groupby('furniture_name'):
 slope=slopes[mapping[name]];fits[name]={'annual_log_growth':slope,'baselines':{}}
 for city,local in g.groupby('locality'):
  fitted=float(np.exp(np.mean(np.log(local.items_sold)+slope*(last-local.year))));actual=float(local[local.year==last].items_sold.iloc[0]);baseline=.65*fitted+.35*actual;fits[name]['baselines'][city]=baseline
  for year in range(current,current+5):
   factor=np.exp(slope*sum(.97**k for k in range(year-last)));rows.append({'locality':city,'furniture_name':name,'year':year,'items_sold':int(round(baseline*factor))})
out=pd.DataFrame(rows);assert len(out)==75 and not out.duplicated(['locality','furniture_name','year']).any();json.dump(rows,open(f'/app/forecast_{current}.json','w'),indent=2);out.to_csv(f'/app/forecast_{current}.csv',index=False);json.dump(fits,open(f'/app/model_{current}.json','w'),indent=2);print('CATEGORY SLOPES', {n:round(v['annual_log_growth'],4) for n,v in fits.items()});print(out.pivot(index=['locality','furniture_name'],columns='year',values='items_sold').to_string())
notes=json.load(open('/app/institutional_knowledge.json'));notes[f'round_{current}']={'previous_score':.943,'method':'Category shared log growth using within-city/product demeaned regression on archived exports and actual feedback. Target levels 65% history adjusted for growth +35% latest actual. Future annual log growth damping .97.','new_evidence':'Repeated NY catalog confirms .21-.22 living/dining, .13 storage/bookcase, .087 king beds. New search/marketing fields correlate with demand but no future field values; excluded from extrapolation.','forecast':f'/app/forecast_{current}.json'};json.dump(notes,open('/app/institutional_knowledge.json','w'),indent=2)
